/** Three pipelines, each applying every rule. */

import {
  rule01,
  rule02,
  rule03,
  rule04,
  rule05,
  rule06,
  rule07,
  rule08,
  rule09,
  rule10,
  rule11,
  rule12,
  rule13,
  rule14,
  rule15,
  rule16,
  rule17,
  rule18,
  rule19,
  rule20,
  rule21,
  rule22,
  rule23,
  rule24,
  rule25,
} from "./rules.ts";

export function ingest(value: string): string {
  return [
    rule01(value),
    rule02(value),
    rule03(value),
    rule04(value),
    rule05(value),
    rule06(value),
    rule07(value),
    rule08(value),
    rule09(value),
    rule10(value),
    rule11(value),
    rule12(value),
    rule13(value),
    rule14(value),
    rule15(value),
    rule16(value),
    rule17(value),
    rule18(value),
    rule19(value),
    rule20(value),
    rule21(value),
    rule22(value),
    rule23(value),
    rule24(value),
    rule25(value),
  ].join("|");
}

export function transform(value: string): string {
  return [
    rule01(value),
    rule02(value),
    rule03(value),
    rule04(value),
    rule05(value),
    rule06(value),
    rule07(value),
    rule08(value),
    rule09(value),
    rule10(value),
    rule11(value),
    rule12(value),
    rule13(value),
    rule14(value),
    rule15(value),
    rule16(value),
    rule17(value),
    rule18(value),
    rule19(value),
    rule20(value),
    rule21(value),
    rule22(value),
    rule23(value),
    rule24(value),
    rule25(value),
  ].join("|");
}

export function publish(value: string): string {
  return [
    rule01(value),
    rule02(value),
    rule03(value),
    rule04(value),
    rule05(value),
    rule06(value),
    rule07(value),
    rule08(value),
    rule09(value),
    rule10(value),
    rule11(value),
    rule12(value),
    rule13(value),
    rule14(value),
    rule15(value),
    rule16(value),
    rule17(value),
    rule18(value),
    rule19(value),
    rule20(value),
    rule21(value),
    rule22(value),
    rule23(value),
    rule24(value),
    rule25(value),
  ].join("|");
}

